select case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end as paid_cohort, sum(amount) as total_amount, count(*) as cnt, round(sum(amount) * 100.0 / sum(sum(amount)) over (), 2) as pct_of_total from payments where method = 'cash' group by case when year(paid_at) < 2024 then 'before_2024' when year(paid_at) = 2024 then '2024' else 'after_2024' end order by pct_of_total desc
